window.PROJECT_H_SCENES["stage_r06h"]=[
{"rowNumber":1,"id":"stage_r06h.mes#2035","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「せ、セックスをするだけなのに、私の手を縛る必要が、どこにあるんですか！」","korean":"그, 그냥 하는 건데 제 손을 묶을 이유가 어디 있어요!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":2,"id":"stage_r06h.mes#2197","kind":"text","speaker":"토모키","english":"","japanese":"大樹「してる途中で気が変わっても、逃げられないようにする為ですよ」","korean":"도중에 마음이 바뀌어도 도망치지 못하게 하려고요.","recordingScript":"","memo":"음성 2","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":3,"id":"stage_r06h.mes#2463","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「……貴方が満足するまでは、決して逃げたりはしません……」","korean":"……하시즈메 씨가 만족하실 때까지는 절대 도망치지 않아요……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":4,"id":"stage_r06h.mes#2609","kind":"text","speaker":"토모키","english":"","japanese":"大樹「なら別に縛ってても問題ないですよね……じゃ、入れますよ」","korean":"그럼 묶어 둬도 문제없죠…… 자, 넣을게요.","recordingScript":"","memo":"음성 4","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":5,"id":"stage_r06h.mes#2753","kind":"text","speaker":"나레이션","english":"","japanese":"早く入れさせろと身を熱く滾らせ主張する肉棒を、俺は茉莉子の股間にぐいっと押し付け陰唇をひしゃげさせていく。","korean":"어서 넣으라고 뜨겁게 달아오른 육봉을 마리코의 가랑이에 힘껏 들이댔다. 음순이 눌려 일그러졌다.","recordingScript":"","memo":"음성 5","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":6,"id":"stage_r06h.mes#3059","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あつっ、あ……ご、ゴムは？」","korean":"뜨거…… 아…… 코, 콘돔은요?","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":7,"id":"stage_r06h.mes#3177","kind":"text","speaker":"토모키","english":"","japanese":"大樹「持ち合わせがありませんし……このままさせてもらいますね」","korean":"가진 게 없어서요…… 이대로 할게요.","recordingScript":"","memo":"음성 7","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":8,"id":"stage_r06h.mes#3321","kind":"text","speaker":"나레이션","english":"","japanese":"それに、犯すならやはり生で膣内の感触を味わわないと、面白くない。","korean":"게다가 범할 거라면 맨살로 질 안의 감촉을 느껴야 재미가 있다.","recordingScript":"","memo":"음성 8","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":9,"id":"stage_r06h.mes#3467","kind":"text","speaker":"나레이션","english":"","japanese":"どうせなら思いっきり乱暴に犯して、一生忘れられない感覚を膣に教え込んでやろう……","korean":"이왕이면 힘껏 거칠게 범해서 평생 잊지 못할 감각을 질에 새겨 주자……","recordingScript":"","memo":"음성 9","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":10,"id":"stage_r06h.mes#3747","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んぐ……あ、貴方の子供なんて孕みたくありません……ぜ、絶対外に、出してください……」","korean":"윽…… 다, 당신 아이 따위 배고 싶지 않아요…… 바, 반드시 밖에 싸 주세요……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":11,"id":"stage_r06h.mes#3921","kind":"text","speaker":"토모키","english":"","japanese":"大樹「……はい、わかりました……いきますよ！」","korean":"……네, 알겠어요…… 갑니다!","recordingScript":"","memo":"음성 11","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":12,"id":"stage_r06h.mes#4049","kind":"text","speaker":"나레이션","english":"","japanese":"茉莉子の腰をグッと引き寄せ、俺は硬く膨らんだペニスをグイグイとねじ込み始めた。","korean":"마리코의 허리를 확 끌어당기고, 단단하고 불룩해진 페니스를 힘주어 밀어 넣기 시작했다.","recordingScript":"","memo":"음성 12","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":13,"id":"stage_r06h.mes#4464","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んあ、あぐぅ……んぐ、んぎぃ……んあ、あぐぅ、うぐぅうう……うあっ、あくっ、んあぁ、あ、んぐ、んひぃ、あ、ああ、ああっ！」","korean":"아, 아윽…… 윽, 으악…… 아, 아윽, 으으윽…… 으아, 으윽, 아아, 아, 윽, 꺅, 아, 아아, 아앗!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":14,"id":"stage_r06h.mes#4676","kind":"text","speaker":"나레이션","english":"","japanese":"濡れが甘く生木を裂くような膣道を、肉棒の硬さで奥へ奥へと突き進ませる。","korean":"충분히 젖지 않아 생나무가 갈라지는 듯한 질 안으로 단단한 육봉을 자꾸 더 깊이 밀어 넣었다.","recordingScript":"","memo":"음성 14","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":15,"id":"stage_r06h.mes#4946","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んぐぐっ、んはぁ……あぐ、んぎぃ……んぐっ、あく、はぁ！　あ、あぐ、んはぁ、んんっ、んふぅ、んはぁ……」","korean":"으윽, 하아…… 아윽, 으악…… 윽, 으윽, 하아! 아, 아윽, 하아, 으응, 으흐, 하아……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":16,"id":"stage_r06h.mes#5140","kind":"text","speaker":"나레이션","english":"","japanese":"苦しむ茉莉子の姿などお構いなしに、膨らんだ亀頭で膣道をゴリゴリと押し開いていく。","korean":"괴로워하는 마리코는 아랑곳하지 않고 불룩한 귀두로 질 안을 비비듯 밀어 벌렸다.","recordingScript":"","memo":"음성 16","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":17,"id":"stage_r06h.mes#5302","kind":"text","speaker":"나레이션","english":"","japanese":"異物の進入に苦しみ薄っすらと背中に汗をかき始めた茉莉子にトドメを刺そうと、俺は一気に奥の壁へ肉棒の先端を叩き込ませた。","korean":"이물질이 들어와 괴로운지 마리코의 등에 땀이 조금씩 맺혔다. 결정타라도 날리듯 육봉 끝을 안쪽 벽에 단숨에 밀어붙였다.","recordingScript":"","memo":"음성 17","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":18,"id":"stage_r06h.mes#5757","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んひぃいいいいぃぃいいいい！！」","korean":"꺄아아아아악!!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":19,"id":"stage_r06h.mes#5997","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んはぁ！　あぐっ、うう……んはぁ、あぐっ……んく……んふぅ……んはぁ……」","korean":"하아! 아윽, 으으…… 하아, 아윽…… 윽…… 으흐…… 하아……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":20,"id":"stage_r06h.mes#6161","kind":"text","speaker":"토모키","english":"","japanese":"大樹「こなれていない感じですけど……もしかして初めてだったんですか？」","korean":"익숙하지 않은 느낌인데…… 혹시 처음이었어요?","recordingScript":"","memo":"음성 20","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":21,"id":"stage_r06h.mes#6568","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んぐっ……んはぁ……そ、それがなんだと言うんですか……さっさと腰を振って、ペニスから汚らわしい粘液を吐き出させてください！」","korean":"윽…… 하아…… 그, 그게 뭐 어쨌다는 거예요…… 얼른 허리를 흔들어서 페니스에서 그 더러운 액이나 쏟아 내세요!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":22,"id":"stage_r06h.mes#6782","kind":"text","speaker":"토모키","english":"","japanese":"大樹「急かさないでくださいよ茉莉子さん……くくっ……」","korean":"그렇게 재촉하지 마세요, 마리코 씨…… 크크……","recordingScript":"","memo":"음성 22","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":23,"id":"stage_r06h.mes#6918","kind":"text","speaker":"나레이션","english":"","japanese":"そんなに早く汚して欲しいなら、何の遠慮の必要もない。","korean":"그렇게 빨리 더럽혀지고 싶다면 사양할 필요도 없다.","recordingScript":"","memo":"음성 23","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":24,"id":"stage_r06h.mes#7052","kind":"text","speaker":"나레이션","english":"","japanese":"奥深く差し込んだまま腰を回し蜜壷をペニスに馴染ませると、俺は猛然と腰を振り始めた。","korean":"깊게 넣은 채 허리를 돌려 질이 페니스에 익숙해지게 한 뒤, 거세게 허리를 흔들기 시작했다.","recordingScript":"","memo":"음성 24","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":25,"id":"stage_r06h.mes#7558","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「はぐっ、あぐぐっ……んくっ、んはぁ！　あ、あぐ、うくっ……んくぅ、あっ、あぐっ、んんっ！」","korean":"하윽, 아으윽…… 윽, 하아! 아, 아윽, 윽…… 으윽, 앗, 아윽, 으응!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":26,"id":"stage_r06h.mes#7738","kind":"text","speaker":"나레이션","english":"","japanese":"先走りと茉莉子自身の微かな膣のヌメリを使い、膨らんだペニスでズリズリと摩擦の強い膣壁を嬲り続けていく。","korean":"페니스 끝에서 나온 액에 마리코의 희미한 애액이 섞였다. 부푼 페니스로 마찰이 강한 질벽을 집요하게 문질렀다.","recordingScript":"","memo":"음성 26","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":27,"id":"stage_r06h.mes#8040","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あひぃ！　あぐ、んぐっ、んあ、ああっ、あはぁ！　あ、あぐっ、んんっ、んぐっ、んふぅ！」","korean":"꺅! 아윽, 윽, 아, 아앗, 아하아! 아, 아윽, 으응, 윽, 으흐!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":28,"id":"stage_r06h.mes#8216","kind":"text","speaker":"토모키","english":"","japanese":"大樹「いいですよ、茉莉子さん……んくぅ、はぁ、はあ……最高だ……」","korean":"좋아요, 마리코 씨…… 으윽, 하아, 하아…… 최고예요……","recordingScript":"","memo":"음성 28","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":29,"id":"stage_r06h.mes#8482","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「はぁ、はぁあ！　あ、あぐぅ……んあ、あぐっ！　んく、んはぁ、あくぅ、んんっ、んふぅ、んんっ……」","korean":"하아, 하아아! 아, 아윽…… 아, 아윽! 윽, 하아, 으윽, 으응, 으흐, 으응……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":30,"id":"stage_r06h.mes#8668","kind":"text","speaker":"나레이션","english":"","japanese":"女の両手を結び、身体の自由の利かない女体を、欲望のまま後ろから犯す……","korean":"여자의 두 손을 묶고, 움직일 수 없는 몸을 욕망이 시키는 대로 뒤에서 범한다……","recordingScript":"","memo":"음성 30","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":31,"id":"stage_r06h.mes#8820","kind":"text","speaker":"나레이션","english":"","japanese":"この良質な演出は俺の興奮を掻き立て、直ぐに中出ししてしまいそうな欲求を堪えて、俺はガムシャラに腰を振り続けていた。","korean":"그 상황에 흥분이 치솟았다. 당장 안에 싸고 싶은 충동을 참으며 정신없이 허리를 흔들었다.","recordingScript":"","memo":"음성 31","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":32,"id":"stage_r06h.mes#9134","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んんっ、んぐぅ、はぁ、あぐっ……んんっ……ま、まだ……んぐっ、んはぁ……で、ですか……あぐっ、んっ、んんっ！」","korean":"으응, 으윽, 하아, 아윽…… 으응…… 아, 아직…… 윽, 하아…… 멀, 멀었어요…… 아윽, 읏, 으응!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":33,"id":"stage_r06h.mes#9334","kind":"text","speaker":"토모키","english":"","japanese":"大樹「もう少し、もう少しで出ますよ……」","korean":"조금만 더, 조금만 더 하면 나와요……","recordingScript":"","memo":"음성 33","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":34,"id":"stage_r06h.mes#9574","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んはぁ！　んぐっ……うくっ、んっ……だ、出す時は……んぐっ、あくっ、んくっ……出す時は外っ、あ、あぐっ！　外にぃ！」","korean":"하아! 윽…… 으윽, 읏…… 싸, 쌀 때는…… 윽, 으윽, 윽…… 쌀 때는 밖에, 아, 아윽! 밖에 싸요!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":35,"id":"stage_r06h.mes#9780","kind":"text","speaker":"토모키","english":"","japanese":"大樹「わかりました！　はぁ、はぁ！　んくっ、もう少し、もう少しで出る、はぁ、んくっ、はぁ、ううっ、で、出るぅ……」","korean":"알겠어요! 하아, 하아! 윽, 조금만 더, 조금만 더 하면 나와요. 하아, 윽, 하아, 으윽, 나, 나온다……","recordingScript":"","memo":"음성 35","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":36,"id":"stage_r06h.mes#10231","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あぐっ！　んあっ、あひぃ、んぐぅ、あ、あぐっ、ああっ、んぐぅ……んぐぅ、あ、あぐぅ、ああっ、あぐぅう！　んはぁあ！」","korean":"아윽! 아, 꺅, 으윽, 아, 아윽, 아앗, 으윽…… 으윽, 아, 아으윽, 아앗, 아으윽! 하아아!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":37,"id":"stage_r06h.mes#10555","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「ああっ！　んあっ、ああっ！　あぐぅう！　ううっ！　はうぅ！　あぐっ！　ああっ、あぐぅうう！！」","korean":"아앗! 아, 아앗! 아으윽! 으윽! 하으! 아윽! 아앗, 아으윽!!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":38,"id":"stage_r06h.mes#10739","kind":"text","speaker":"토모키","english":"","japanese":"大樹「あっ、で、出るぅ！」","korean":"앗, 나, 나온다!","recordingScript":"","memo":"음성 38","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":39,"id":"stage_r06h.mes#10885","kind":"text","speaker":"나레이션","english":"","japanese":"俺は亀頭を勢いよく奥へめり込ませると、茉莉子の膣中へ熱い欲望の塊を吐き出させた。","korean":"귀두를 힘껏 안쪽으로 밀어 넣고, 마리코의 질 안에 차오른 뜨거운 욕망을 쏟았다.","recordingScript":"","memo":"음성 39","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":40,"id":"stage_r06h.mes#11397","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んあぁああ！！　あぐっ、んあっ！？　あぐ、ぬ、抜いて！　い、嫌ぁ！　い、嫌っ、出てる、中に出てるぅ！」","korean":"아아아!! 아윽, 아?! 아윽, 빼, 빼요! 시, 싫어요! 시, 싫어, 나오잖아, 안에 나오잖아!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":41,"id":"stage_r06h.mes#11589","kind":"text","speaker":"나레이션","english":"","japanese":"逃げようと腰を振る茉莉子の尻を渾身の力でガッチリと押さえ、肉棒の根元から込み上げるネバネバとした白濁を次々と子宮へ注ぎ込んでやる。","korean":"빠져나가려고 허리를 흔드는 마리코의 엉덩이를 온 힘을 다해 붙들었다. 육봉 뿌리에서 차오르는 끈적한 정액을 자궁에 잇따라 쏟아 넣었다.","recordingScript":"","memo":"음성 41","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":42,"id":"stage_r06h.mes#11919","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「は、離して！　あ、あくっ、い、嫌、嫌ぁ！　気持ち悪いぃ……あ、あぐぅ……ああぁ……な、中に、中に出すなんて……こ、この……このケダモノォ！」","korean":"노, 놓으라고요! 아, 으윽, 시, 싫어요, 싫어! 기분 나빠…… 아, 아으윽…… 아아…… 아, 안에, 안에 싸다니…… 이, 이…… 이 짐승 같은 놈!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":43,"id":"stage_r06h.mes#12149","kind":"text","speaker":"토모키","english":"","japanese":"大樹「すみません……抜こうと思ったんですが、つい我慢できずに……」","korean":"죄송해요…… 빼려고 했는데 그만 참지 못하고……","recordingScript":"","memo":"음성 43","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":44,"id":"stage_r06h.mes#12297","kind":"text","speaker":"나레이션","english":"","japanese":"吐精を終えても尚硬いペニスで、膣奥の精液を掻き回すようにグリグリと動かしていく。","korean":"사정 뒤에도 단단한 페니스를 깊이 넣은 채, 질 안쪽에 고인 정액을 휘젓듯 움직였다.","recordingScript":"","memo":"음성 44","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":45,"id":"stage_r06h.mes#12717","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あぐっ……さ、最初から嘘をついて中で出す気だったんですね……この屑……」","korean":"아윽…… 처, 처음부터 거짓말하고 안에 쌀 생각이었군요…… 이 쓰레기……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":46,"id":"stage_r06h.mes#12879","kind":"text","speaker":"토모키","english":"","japanese":"大樹「はは……」","korean":"하하……","recordingScript":"","memo":"음성 46","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":47,"id":"stage_r06h.mes#13144","kind":"text","speaker":"나레이션","english":"","japanese":"笑いながら肉棒を引き抜くと、肉棒には破瓜の証がこびり付いていた。","korean":"웃으면서 육봉을 빼자, 처음이었다는 걸 보여 주는 핏자국이 묻어 있었다.","recordingScript":"","memo":"음성 47","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":48,"id":"stage_r06h.mes#13290","kind":"text","speaker":"토모키","english":"","japanese":"大樹「処女だったんですね……初めてのおちんちんはどうでした？　痛くなかったですか？」","korean":"처녀였네요…… 처음으로 자지를 받아 본 기분이 어땠어요? 아프진 않았어요?","recordingScript":"","memo":"음성 48","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":49,"id":"stage_r06h.mes#13714","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「痛いに決まっています！　んぐっ、こ、これで……満足しましたか？」","korean":"당연히 아프죠! 윽, 이, 이제…… 만족하셨나요?","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":50,"id":"stage_r06h.mes#13868","kind":"text","speaker":"토모키","english":"","japanese":"大樹「いや、全然……ほら、おちんちんの硬さがわかるでしょう？」","korean":"아뇨, 전혀요…… 자, 자지가 얼마나 단단한지 느껴지죠?","recordingScript":"","memo":"음성 50","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":51,"id":"stage_r06h.mes#14012","kind":"text","speaker":"나레이션","english":"","japanese":"先ほど注いだ精液をボトボトと零す膣口に、グイグイと亀頭を押し当てると、茉莉子は脅えるようにビクリと腰を震わせていく。","korean":"방금 쏟아 넣은 정액이 뚝뚝 떨어지는 질 입구에 귀두를 힘줘 대자, 마리코는 겁먹은 듯 허리를 움찔했다.","recordingScript":"","memo":"음성 51","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":52,"id":"stage_r06h.mes#14328","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んぐっ！　き、気持ち悪い……あぐっ、あくぅ……だったら、その汚物を私の中に差し込んで、さっさと満足して、私を解放して下さい……」","korean":"윽! 기, 기분 나빠…… 아윽, 으윽…… 그럼 그 더러운 걸 제 안에 넣고 얼른 만족한 다음 저를 풀어 주세요……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":53,"id":"stage_r06h.mes#14546","kind":"text","speaker":"토모키","english":"","japanese":"大樹（……さっさと解放なんかするもんかよ……）","korean":"……얼른 풀어 줄 리가 있나……","recordingScript":"","memo":"음성 53","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":54,"id":"stage_r06h.mes#14674","kind":"text","speaker":"토모키","english":"","japanese":"大樹（いい機会だし……薬を茉莉子で試してみるとするか……）","korean":"좋은 기회니…… 마리코한테 약을 시험해 볼까……","recordingScript":"","memo":"음성 54","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":55,"id":"stage_r06h.mes#14814","kind":"text","speaker":"토모키","english":"","japanese":"大樹「……今度は、茉莉子さんも楽しめるようにしてあげますよ」","korean":"……이번엔 마리코 씨도 즐길 수 있게 해 드릴게요.","recordingScript":"","memo":"음성 55","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":56,"id":"stage_r06h.mes#15096","kind":"text","speaker":"나레이션","english":"","japanese":"ケースから薬を取り出すと、尻肉を押さえながら、菊門にずぶりと薬を埋め込んでいく。","korean":"약통에서 약을 꺼내 엉덩이 살을 누른 채 항문에 밀어 넣었다.","recordingScript":"","memo":"음성 56","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":57,"id":"stage_r06h.mes#15376","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「な！？　ど、どこに触っているんですか！？　い、嫌！　や、やめなさい！　やめ、やめてぇ！」","korean":"뭐예요?! 어, 어디를 만지는 거예요?! 시, 싫어! 그, 그만해요! 그만, 그만하라고요!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":58,"id":"stage_r06h.mes#15554","kind":"text","speaker":"나레이션","english":"","japanese":"尻穴を弄られる不快感に茉莉子は身体を暴れさせるものの、初体験で消耗した身体では思うように動けないのか、片手でも容易に抑える事が出来る。","korean":"항문을 건드리는 느낌에 마리코는 불쾌해하며 몸부림쳤다. 첫 경험에 기운이 빠져 몸이 말을 듣지 않는지, 한 손으로도 쉽게 누를 수 있었다.","recordingScript":"","memo":"음성 58","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":59,"id":"stage_r06h.mes#15770","kind":"text","speaker":"토모키","english":"","japanese":"大樹（ふふ……やっぱり、縛っておいて正解だったな……）","korean":"후후…… 묶어 두길 잘했네……","recordingScript":"","memo":"음성 59","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":60,"id":"stage_r06h.mes#16024","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あ、あぐぅ……こ、この変態……そんな所に指を突っ込むなんて……んぐっ……」","korean":"아, 아으윽…… 이, 이 변태…… 그런 데다 손가락을 넣다니…… 윽……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":61,"id":"stage_r06h.mes#16188","kind":"text","speaker":"나레이션","english":"","japanese":"逃げようとする腰を掴んだまま、１錠、また１錠と菊門に錠剤を埋め込んでいき……","korean":"도망치려는 허리를 붙잡고, 한 알, 또 한 알 항문에 밀어 넣었다……","recordingScript":"","memo":"음성 61","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":62,"id":"stage_r06h.mes#16486","kind":"text","speaker":"나레이션","english":"","japanese":"トドメに先ほどまで飲んでいた酒瓶を、尻穴に差し込んでやった。","korean":"마지막으로 방금까지 마시던 술병을 항문에 밀어 넣었다.","recordingScript":"","memo":"음성 62","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":63,"id":"stage_r06h.mes#16746","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「ひゃあ！　な、何、何してるの！？　い、嫌、あ、あぐっ、ああっ、ああぁ！」","korean":"꺅! 뭐, 뭐, 뭐 하는 거예요?! 시, 싫어, 아, 아윽, 아앗, 아아!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":64,"id":"stage_r06h.mes#16908","kind":"text","speaker":"토모키","english":"","japanese":"大樹「お酒ですよ……茉莉子さん、苦労してそうなんでお酒をご馳走してあげますよ……」","korean":"술이에요…… 마리코 씨가 고생하는 것 같아서 한잔 대접하려고요……","recordingScript":"","memo":"음성 64","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":65,"id":"stage_r06h.mes#17072","kind":"text","speaker":"나레이션","english":"","japanese":"酒は、薬の効きを良くする。","korean":"술을 마시면 약이 더 잘 듣는다.","recordingScript":"","memo":"음성 65","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":66,"id":"stage_r06h.mes#17180","kind":"text","speaker":"나레이션","english":"","japanese":"たとえ茉莉子に薬が効かなかったとしても、酔わせさえすれば余計な力も抜けより犯しやすくなるというもの。","korean":"약이 안 듣더라도 취하면 몸에 힘이 빠져 범하기 쉬워지겠지.","recordingScript":"","memo":"음성 66","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":67,"id":"stage_r06h.mes#17620","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あぐっ、は、入ってくるぅ……や、止めて……あ、あぐ……あくぅ……あ、あふ……あ、あぐぅ、あっ、あひぃ！」","korean":"아윽, 드, 들어와요…… 그, 그만…… 아, 아윽…… 으윽…… 아, 하으…… 아, 아으윽, 앗, 꺅!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":68,"id":"stage_r06h.mes#17932","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あぐぅ……んあ、ああっ……あ、熱い……お腹が……お腹が熱いぃ……あぐぅ……ああっ……んあぁぁ……」","korean":"아으윽…… 아, 아앗…… 뜨, 뜨거워요…… 배가…… 배가 뜨거워요…… 아으윽…… 아앗…… 아아아……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":69,"id":"stage_r06h.mes#18120","kind":"text","speaker":"나레이션","english":"","japanese":"薬と酒を身体に馴染ませる為、俺は軽く汗ばむ茉莉子のムッチリとした尻を丹念にもみ続けた……","korean":"약과 술이 몸에 퍼지도록, 땀이 살짝 밴 마리코의 도톰한 엉덩이를 찬찬히 주물렀다……","recordingScript":"","memo":"음성 69","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":70,"id":"stage_r06h.mes#19722","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あふぅ、ああっ……んあ、ああぁん……んあ、ああぁ……あはぁ……ああぁん」","korean":"하으, 아앗…… 아, 아아앙…… 아, 아아…… 아하아…… 아아앙.","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":71,"id":"stage_r06h.mes#20021","kind":"text","speaker":"나레이션","english":"","japanese":"時間が経つにつれ色香が増していく茉莉子……","korean":"시간이 흐를수록 마리코의 몸에서 야릇한 기색이 짙어졌다……","recordingScript":"","memo":"음성 72","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":72,"id":"stage_r06h.mes#20145","kind":"text","speaker":"나레이션","english":"","japanese":"彼女に注ぎ込んだ精液を洗い落とすかのように、陰唇から愛液が次々とあふれ出し太股を濡らしていく。","korean":"안에 쏟아 넣은 정액을 씻어 내기라도 하듯, 음순 사이로 애액이 넘쳐 허벅지를 적셨다.","recordingScript":"","memo":"음성 73","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":73,"id":"stage_r06h.mes#20439","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あ、あぐぅ……あ、熱い……あそこが……熱いぃ……な、何……あ、あうぅ……何、これ……何なの……あぐぅ、あひぃいい……」","korean":"아, 아으윽…… 뜨, 뜨거워요…… 거기가…… 뜨거워요…… 뭐, 뭐예요…… 아, 으윽…… 뭐, 이거…… 뭐죠…… 아으윽, 꺄악……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":74,"id":"stage_r06h.mes#20841","kind":"text","speaker":"나레이션","english":"","japanese":"十分に発情した膣口にペニスの先端を押し付けると、まるで別の女の膣口をあてがったかのようにスルリと亀頭が飲み込まれた。","korean":"잔뜩 달아오른 질 입구에 끝을 누르자 마치 다른 여자의 몸을 대고 있는 것처럼 귀두가 쑥 빨려 들어갔다.","recordingScript":"","memo":"음성 75","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":75,"id":"stage_r06h.mes#21157","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あひぃいいぃぃ！　あふぅうう！　ああっ！　あはぁ！　あふぅ、あぐっ、んんっ、んはぁ、あぐっ、んあぁ、んくうぅううう……」","korean":"꺄아악! 하으으! 아앗! 아하아! 하으, 아윽, 으응, 하아, 아윽, 아아, 으으윽……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":76,"id":"stage_r06h.mes#21367","kind":"text","speaker":"토모키","english":"","japanese":"大樹「はは……効果抜群……凄いもんだな……」","korean":"하하…… 효과가 확실하네…… 대단한데……","recordingScript":"","memo":"음성 77","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":77,"id":"stage_r06h.mes#21611","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んぐっ、あっ、あぐぅう……あはぁ、ふぅう……わ、私に……私の身体に何を……な、何をしたんですか……」","korean":"윽, 앗, 아으윽…… 아하아, 후우…… 저, 저한테…… 제 몸에 무슨…… 무, 무슨 짓을 하신 거예요……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":78,"id":"stage_r06h.mes#21801","kind":"text","speaker":"토모키","english":"","japanese":"大樹「何って……何かするのはこれからじゃないですか！」","korean":"무슨 짓이라니…… 이제부터 할 참인데요!","recordingScript":"","memo":"음성 79","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":79,"id":"stage_r06h.mes#21937","kind":"text","speaker":"나레이션","english":"","japanese":"腰をがっしりと掴むと、硬く怒張したペニスを杭に見立て、俺は膣奥にズンッと肉棒を打ち付ける。","korean":"허리를 단단히 움켜쥐고, 딱딱하게 선 페니스를 말뚝처럼 질 안쪽으로 힘껏 밀어 넣었다.","recordingScript":"","memo":"음성 80","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":80,"id":"stage_r06h.mes#22421","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「ひぃああああああ！　あ、あふぅ！　あ、ああっ、あぐぅ、い、いくぅ、いいっ、いくぅう！　いくっ、いくぅ、いくぅ！　い、いくぅうううううぅぅぅうううう！！！」","korean":"꺄아아악! 아, 하으! 아, 아앗, 아으윽, 가, 가요, 아, 가요! 가요, 가요, 가요! 가, 가아아아!!!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":81,"id":"stage_r06h.mes#22665","kind":"text","speaker":"나레이션","english":"","japanese":"乱暴に突き入れただけで果てたはしたない蜜壷は、快感に震えペニスを扱きたてていく。","korean":"거칠게 밀어 넣기만 했는데도 절정에 이른 질이 쾌감에 떨며 페니스를 훑었다.","recordingScript":"","memo":"음성 82","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":82,"id":"stage_r06h.mes#22945","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んはぁ！　あ、あぐぅ……ん、んぐぅ、んおぉお、おう、おうぅう……あ、あぐぅ……ふぅ、んふぅう……」","korean":"하아! 아, 아으윽…… 으, 으윽, 오오, 오, 오오…… 아, 아으윽…… 후우, 으흐으……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":83,"id":"stage_r06h.mes#23133","kind":"text","speaker":"나레이션","english":"","japanese":"薬の力により覚醒したメスの喜びを俺へ見せ付けるように、茉莉子は全身を揺らし艶かしく悶えてみせる。","korean":"약으로 깨어난 욕정을 내게 보여 주려는 듯, 마리코는 온몸을 흔들며 야릇하게 몸을 뒤틀었다.","recordingScript":"","memo":"음성 84","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":84,"id":"stage_r06h.mes#23311","kind":"text","speaker":"토모키","english":"","japanese":"大樹「ふふ……気持ち良さそうですね、茉莉子さん……でも、締まりがなくなったのはいただけないなぁ……」","korean":"후후…… 기분 좋아 보이네요, 마리코 씨…… 하지만 조이는 힘이 없어진 건 영 별로네요……","recordingScript":"","memo":"음성 85","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":85,"id":"stage_r06h.mes#23778","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あくぅう……あぁ、あぁん……い、いい……おちんぽ……おちんぽがこんなに気持ちいいなんてぇ……あ、あぐっ……あ、ああっ、あふぅ、あっ、あっ、あああっ！」","korean":"으으윽…… 아아, 아앙…… 조, 좋아요…… 자지…… 자지가 이렇게 기분 좋을 줄은…… 아, 아윽…… 아, 아앗, 하으, 앗, 앗, 아아앗!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":86,"id":"stage_r06h.mes#24018","kind":"text","speaker":"토모키","english":"","japanese":"大樹「茉莉子さん、俺を満足させてくれるんでしょ？　もっと締めてくれませんか？」","korean":"마리코 씨, 저를 만족시켜 주기로 했죠? 좀 더 조여 주실래요?","recordingScript":"","memo":"음성 87","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":87,"id":"stage_r06h.mes#24296","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あ、あん、あぐぅ！　く、くる、きちゃうぅ、はあっ、ああっ、動いていないのにぃ、い、いくぅ、いくぅ、いくぅう！　あ、あぐぅ、ああっ、ああぁん！」","korean":"아, 앙, 아으윽! 오, 온다, 오고 있어요. 하앗, 아앗, 움직이지도 않는데, 가, 가요, 가요, 가요! 아, 아으윽, 아앗, 아아앙!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":88,"id":"stage_r06h.mes#24646","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んあひぃいいいいいぃぃぃいいいいい！！！」","korean":"꺄아아아악!!!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":89,"id":"stage_r06h.mes#24896","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んはぁ、あぐっ、あふぅ、はぁああ……」","korean":"하아, 아윽, 하으, 하아아……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":90,"id":"stage_r06h.mes#25024","kind":"text","speaker":"나레이션","english":"","japanese":"再び一人だけ絶頂を極め、茉莉子は壊れた人形のようにガクガクと身体を震わせていく。","korean":"혼자 다시 절정에 이른 마리코는 고장 난 인형처럼 몸을 덜덜 떨었다.","recordingScript":"","memo":"음성 91","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":91,"id":"stage_r06h.mes#25186","kind":"text","speaker":"나레이션","english":"","japanese":"そして俺の事など忘れたかのように、茉莉子は自分の肉欲だけを満たそうとゆるゆると腰を振り、肉棒の摩擦で新たな快感を求め始めた……","korean":"그러고는 나를 잊기라도 한 듯, 자기 욕정을 채우려고 허리를 느릿하게 흔들며 육봉의 마찰에서 또 다른 쾌감을 찾기 시작했다……","recordingScript":"","memo":"음성 92","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":92,"id":"stage_r06h.mes#25512","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んんっ、し、紫衣お嬢様、紫衣お嬢様ぁ……これ……んっく、ち、ちんぽ、ちんぽすごいですぅ……あ、ああっ、んふぅ！」","korean":"으응, 시, 시에 아가씨, 시에 아가씨…… 이거…… 윽, 자, 자지가, 자지가 대단해요…… 아, 아앗, 으흐!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":93,"id":"stage_r06h.mes#25714","kind":"text","speaker":"나레이션","english":"","japanese":"大量の愛液で滑りが良くなったのはいいが……薬の効力で身体の力どころか締め付けや頭のネジまでも緩くなってしまっては話にならない。","korean":"쏟아지는 애액 덕에 미끄러워진 건 좋지만…… 약효에 몸의 힘도, 조이는 힘도 풀리고 정신줄까지 놓아 버리면 말이 안 된다.","recordingScript":"","memo":"음성 94","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":94,"id":"stage_r06h.mes#25922","kind":"text","speaker":"토모키","english":"","japanese":"大樹（何事も適量がいいって事か……）","korean":"뭐든 적당한 게 좋다는 거군……","recordingScript":"","memo":"음성 95","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":95,"id":"stage_r06h.mes#26040","kind":"text","speaker":"토모키","english":"","japanese":"大樹「まったく……これじゃあ、茉莉子さんを楽しませてるだけじゃないですか……ふふ……俺にも楽しませてくださいよ……」","korean":"참…… 이래선 마리코 씨만 좋은 거잖아요…… 후후…… 저도 좀 즐기게 해 주세요……","recordingScript":"","memo":"음성 96","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":96,"id":"stage_r06h.mes#26432","kind":"text","speaker":"나레이션","english":"","japanese":"パンパンに膨らんだ肉棒をズルリと膣内から引き抜くと、俺は先ほどから息を吸うようにパクパクと動く尻穴に亀頭を押し当てていく。","korean":"잔뜩 부풀어 오른 육봉을 질에서 쑥 빼냈다. 아까부터 숨을 들이쉬는 것처럼 움찔대던 항문에 귀두를 눌렀다.","recordingScript":"","memo":"음성 97","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":97,"id":"stage_r06h.mes#26636","kind":"text","speaker":"토모키","english":"","japanese":"大樹「……茉莉子さんのもう一つの初めても……俺が貰ってあげますね……」","korean":"……마리코 씨의 또 다른 처음도…… 제가 가져갈게요……","recordingScript":"","memo":"음성 98","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":98,"id":"stage_r06h.mes#26788","kind":"text","speaker":"나레이션","english":"","japanese":"窄まりの中心に狙いを定めると、俺はメリメリと亀頭を埋め込み始めた。","korean":"오므라든 구멍 한가운데에 귀두를 겨누고 억지로 밀어 넣기 시작했다.","recordingScript":"","memo":"음성 99","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":99,"id":"stage_r06h.mes#27248","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んひぃいいい！　あ、あぐぅ、な、なにっ、あっあぐぅ、んあぁあああああ！」","korean":"꺄아악! 아, 아으윽, 뭐, 뭐예요, 앗, 아으윽, 아아아아!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":100,"id":"stage_r06h.mes#27410","kind":"text","speaker":"나레이션","english":"","japanese":"膣ほどではないが肛門も弛緩していた為、初めてとは思えないほど容易に肉棒はズブズブと直腸の奥へと飲み込まれていく。","korean":"질만큼은 아니어도 항문도 힘이 풀려 있었다. 처음이라고는 믿기 힘들 만큼 쉽게 육봉이 직장 깊숙이 들어갔다.","recordingScript":"","memo":"음성 101","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":101,"id":"stage_r06h.mes#27913","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あひぃいいいいいいぃぃぃいいい！」","korean":"꺄아아아악!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":102,"id":"stage_r06h.mes#28037","kind":"text","speaker":"토모키","english":"","japanese":"大樹「ふぅ……ユルユルになったマンコと違って、こっちはキツキツですね……」","korean":"후우…… 헐거워진 보지와 달리, 여긴 꽉 조이네요……","recordingScript":"","memo":"음성 103","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":103,"id":"stage_r06h.mes#28451","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あ、あくっ……んぐ、な、何をしているんですか、貴方は！」","korean":"아, 으윽…… 윽, 무, 무슨 짓을 하는 거예요, 당신!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":104,"id":"stage_r06h.mes#28597","kind":"text","speaker":"토모키","english":"","japanese":"大樹「あっ、もしかして、正気に戻りました？　何ってオチンチンを茉莉子さんのお尻に入れているんですよ」","korean":"아, 혹시 제정신이 돌아왔어요? 무슨 짓이긴요. 마리코 씨 엉덩이에 자지를 넣고 있죠.","recordingScript":"","memo":"음성 105","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":105,"id":"stage_r06h.mes#28897","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「っ！？　お、お尻に……ペニスを？　んく、あぐぅ……こ、この変態！　んくっ、あぐっ……は、早く抜きなさい！」","korean":"……?! 엉, 엉덩이에…… 페니스를요? 윽, 아으윽…… 이, 이 변태! 윽, 아윽…… 어, 얼른 빼요!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":106,"id":"stage_r06h.mes#29093","kind":"text","speaker":"토모키","english":"","japanese":"大樹「そうはいってもおまんこじゃ茉莉子さんは良くても、緩すぎて俺が気持ちよくなれませんからね……こっちの穴で一緒に気持ちよくなりましょう」","korean":"보지로는 마리코 씨야 좋아도 너무 헐거워서 저는 기분이 안 좋거든요…… 이쪽 구멍으로 같이 기분 좋아져요.","recordingScript":"","memo":"음성 107","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":107,"id":"stage_r06h.mes#29431","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んぐぅ、あ、あぐぅ……あ、貴方と違って異常な性癖は持ち合わせていません！」","korean":"으윽, 아, 아으윽…… 다, 당신과 달리 제게는 그런 비정상적인 취향 없어요!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":108,"id":"stage_r06h.mes#29713","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「お、お尻の穴を犯されて……んぐっ、き、気持ちよくなんてなれるわけが……」","korean":"하, 항문을 범하는데…… 윽, 기, 기분이 좋을 수가……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":109,"id":"stage_r06h.mes#30157","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あ、あぐぅ……気持ちよくなんて……男に……男に犯されて……気持ちよくなるわけが……不快なだけ……んあぁぁ」","korean":"아, 아으윽…… 기분이 좋을 수가…… 남자한테…… 남자한테 범해지면서…… 좋을 리가…… 불쾌할 뿐…… 아아아……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":110,"id":"stage_r06h.mes#30353","kind":"text","speaker":"나레이션","english":"","japanese":"最初こそお尻の中に異物を入れられた事に鳥肌を立てていたものの……茉莉子も肉棒を差し込まれる感覚に徐々に慣れ始めたのだろう。","korean":"처음에는 엉덩이 안에 이물질이 들어와 소름이 돋았지만…… 마리코도 육봉이 들어오는 감각에 조금씩 익숙해지는 모양이다.","recordingScript":"","memo":"음성 111","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":111,"id":"stage_r06h.mes#30557","kind":"text","speaker":"나레이션","english":"","japanese":"強引に広げられていた括約筋はペニスを揉むように蠢き、肌はしっとりと濡れ漏れ出す声色もカドが落ちていく。","korean":"억지로 벌어진 괄약근이 페니스를 주무르듯 움직였다. 피부에는 촉촉하게 땀이 배고, 입에서 새는 소리도 한결 부드러워졌다.","recordingScript":"","memo":"음성 112","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":112,"id":"stage_r06h.mes#30741","kind":"text","speaker":"나레이션","english":"","japanese":"……異常な性癖と罵った茉莉子自身がアナルセックスに目覚めようとするその様をニヤニヤと見守りながら、俺はゆっくりと腰を振り始めた。","korean":"……비정상적인 취향이라고 욕한 마리코가 정작 항문 섹스에 눈뜨려는 모습을 히죽거리며 보다가, 천천히 허리를 움직이기 시작했다.","recordingScript":"","memo":"음성 113","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":113,"id":"stage_r06h.mes#31296","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あぐぅ、あっ……うごか……ないで……あくっ、あ……き、気持ち、気持ちわるい……あぐぅ……あ、ああっ……ん、んくぅ……」","korean":"아으윽, 앗…… 움직이지…… 마요…… 으윽, 아…… 기, 기분, 기분 나빠요…… 아으윽…… 아, 아앗…… 으, 으윽……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":114,"id":"stage_r06h.mes#31622","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んぐっ、んはぁ……お、男のモノで……んっ、んぐぅ、お尻の穴を犯されて……あぐっ、ああっ……あ、感じるはずが……あくっ、んんっ！」","korean":"윽, 하아…… 나, 남자 물건에…… 읏, 으윽, 엉덩이 구멍을 범해지면서…… 아윽, 아앗…… 느, 느낄 리가…… 으윽, 으응!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":115,"id":"stage_r06h.mes#31840","kind":"text","speaker":"토모키","english":"","japanese":"大樹「男、男っていいますけど……女同士ならいいとでもいうんですか？」","korean":"남자, 남자 하시는데…… 여자끼리라면 괜찮다는 거예요?","recordingScript":"","memo":"음성 116","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":116,"id":"stage_r06h.mes#32248","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あ、あぐっ、んんっ、お、男なんか……け、ケダモノばかり……女同士の方がいいにきまっています！」","korean":"아, 아윽, 으응, 나, 남자들은…… 지, 짐승밖에 없어요…… 여자끼리가 훨씬 나은 게 당연하잖아요!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":117,"id":"stage_r06h.mes#32432","kind":"text","speaker":"토모키","english":"","japanese":"大樹（へぇ……茉莉子さんはレズだったわけだ……くくっ……こいつは驚きだ……）","korean":"오…… 마리코 씨는 여자를 좋아했구나…… 크크…… 뜻밖인데……","recordingScript":"","memo":"음성 118","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":118,"id":"stage_r06h.mes#32590","kind":"text","speaker":"토모키","english":"","japanese":"大樹「……茉莉子さんは、恋人いるんですか？」","korean":"……마리코 씨, 연인 있으세요?","recordingScript":"","memo":"음성 119","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":119,"id":"stage_r06h.mes#32834","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んはぁ、あ、あぐっ……そんな事……貴方に、関係ありません……んぐぅ、あ、あくぅ……んん、んはぁ……」","korean":"하아, 아, 아윽…… 그런 건…… 하시즈메 씨와 상관없어요…… 으윽, 아, 으윽…… 으응, 하아……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":120,"id":"stage_r06h.mes#33024","kind":"text","speaker":"토모키","english":"","japanese":"大樹「そうか……何時も一緒にいる、紫衣お嬢様ですね？」","korean":"그렇군요…… 늘 붙어 있는 시에 아가씨죠?","recordingScript":"","memo":"음성 121","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":121,"id":"stage_r06h.mes#33278","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んんっ、んはぁ……何を言っても無駄です……あぐ、んんっ……わ、私は、貴方の言う事なんて……ん、んくっ……絶対に聞きません……」","korean":"으응, 하아…… 무슨 말을 해도 헛수고예요…… 아윽, 으응…… 저, 저는 당신 말 같은 거…… 으, 윽…… 절대 안 들을 거예요……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":122,"id":"stage_r06h.mes#33494","kind":"text","speaker":"토모키","english":"","japanese":"大樹「ふぅうん……絶対に……ねぇ……」","korean":"흐으음…… 절대로…… 말이에요……","recordingScript":"","memo":"음성 123","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":123,"id":"stage_r06h.mes#33614","kind":"text","speaker":"나레이션","english":"","japanese":"俺は意地を張ろうとする茉莉子を素直にさせる為、抽送を速めアナルへの刺激を強めた。","korean":"고집을 부리는 마리코가 말을 듣게 하려고, 허리를 더 빠르게 움직여 항문에 닿는 자극을 강하게 했다.","recordingScript":"","memo":"음성 124","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":124,"id":"stage_r06h.mes#34031","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あぐぅ！　ああっ、あひぃ！　ああぁん！　は、速いぃ、駄目っ、速いぃ！」","korean":"아으윽! 아앗, 꺅! 아아앙! 빠, 빨라요, 안 돼, 너무 빨라요!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":125,"id":"stage_r06h.mes#34191","kind":"text","speaker":"토모키","english":"","japanese":"大樹「正直に言わないと、もっともっと速くしますよ？」","korean":"솔직하게 말 안 하면 더, 더 빨리 할 거예요.","recordingScript":"","memo":"음성 126","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":126,"id":"stage_r06h.mes#34443","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んあっ、あひぃ！　き、きちゃうぅ、嫌、嫌ぁ！　お尻、お尻でいくぅ！　と、止めて……お尻で、お尻でなんていきたくないぃ！　いきたくないぃ！」","korean":"아, 꺅! 오, 오고 있어요, 싫어, 싫다고요! 엉덩이, 엉덩이로 가 버려요! 그, 그만…… 엉덩이로, 엉덩이로는 가기 싫어요! 가기 싫다고요!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":127,"id":"stage_r06h.mes#34789","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「こ、こいびと、恋人ぉ！　あぐっ、んはぁ！　お、お嬢様と、私は……ん、んあっ！　恋人ですぅ！」","korean":"여, 연인, 연인이에요! 아윽, 하아! 아, 아가씨랑 저는…… 으, 아! 연인이라고요!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":128,"id":"stage_r06h.mes#34971","kind":"text","speaker":"나레이션","english":"","japanese":"答えを言わせ満足した俺は、肛門の内側をめくるようにゆっくりと尻穴から肉棒を引き抜いていく。","korean":"대답을 듣고 만족한 나는 항문 안쪽이 따라 나올 만큼 천천히 육봉을 뺐다.","recordingScript":"","memo":"음성 129","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":129,"id":"stage_r06h.mes#35439","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んおぉお、おふぅ、んんっ……んはぁ……んくっ……」","korean":"오오, 오흐, 으응…… 하아…… 윽……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":130,"id":"stage_r06h.mes#35579","kind":"text","speaker":"토모키","english":"","japanese":"大樹「へぇ、そうだったんですか……ちなみに、ここに来るのは自分の意思でって言ってましたよね？」","korean":"아, 그랬군요…… 그런데 여기 온 건 본인 뜻이라고 하셨죠?","recordingScript":"","memo":"음성 131","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":131,"id":"stage_r06h.mes#35873","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「はぁはぁ！　んぐっ……そ、そうです……お嬢様には言っていません……それが何か？」","korean":"하아, 하아! 윽…… 그, 그래요…… 아가씨께는 말씀 안 드렸어요…… 그게 왜요?","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":132,"id":"stage_r06h.mes#36043","kind":"text","speaker":"토모키","english":"","japanese":"大樹「同性愛者の茉莉子さんは交渉の為とはいえ、恋人に断りもなく男に初めてを捧げちゃっていいんですか？」","korean":"여자만 좋아하는 마리코 씨가 협상 때문이라고 해도, 연인한테 알리지도 않고 남자한테 처음을 줘도 돼요?","recordingScript":"","memo":"음성 133","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":133,"id":"stage_r06h.mes#36345","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「男に抱かれたから浮気だとでも？　……馬鹿馬鹿しい……」","korean":"남자랑 잤다고 바람이라고 하시게요? ……말도 안 돼요……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":134,"id":"stage_r06h.mes#36489","kind":"text","speaker":"토모키","english":"","japanese":"大樹「野郎は愛し合う対象ではないから、犬猫みたいなもので浮気には入らないと？」","korean":"남자는 사랑하는 상대가 아니라 개나 고양이 같은 거라서, 바람피운 게 아니라는 건가요?","recordingScript":"","memo":"음성 135","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":135,"id":"stage_r06h.mes#36767","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「当然です……事が済んだ後に事情を話せば、紫衣お嬢様は私を許すに決まっています」","korean":"당연하죠…… 일이 끝나고 사정을 설명하면 시에 아가씨는 당연히 용서해 주실 거예요.","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":136,"id":"stage_r06h.mes#37053","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「それに男は破瓜を特別視するらしいですが……膣を裂傷させた事を誇るなんて、頭がおかしいとしか思えません」","korean":"남자들은 처음을 대단한 일처럼 여긴다지만…… 질에 상처를 냈다고 자랑하다니, 제정신이라고는 생각할 수 없어요.","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":137,"id":"stage_r06h.mes#37245","kind":"text","speaker":"토모키","english":"","japanese":"大樹「……大体、茉莉子さんの言いたい事はわかりました……」","korean":"……마리코 씨가 무슨 말을 하고 싶은지 대충 알겠어요……","recordingScript":"","memo":"음성 138","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":138,"id":"stage_r06h.mes#37525","kind":"text","speaker":"나레이션","english":"","japanese":"お喋りで心に余裕を取り戻しつつある茉莉子の意識をペニスへ戻す為、肉棒の先端を再び尻穴に潜り込ませていく。","korean":"얘기를 하며 여유를 되찾던 마리코의 정신을 페니스에 돌려놓으려고 육봉 끝을 다시 항문에 밀어 넣었다.","recordingScript":"","memo":"음성 139","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":139,"id":"stage_r06h.mes#37829","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んぎっ！　んひぃいいい！　んはぁ！　あぐぅ……」","korean":"으악! 꺄악! 하아! 아으윽……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":140,"id":"stage_r06h.mes#37967","kind":"text","speaker":"토모키","english":"","japanese":"大樹「俺は約束通り紫衣お嬢様に協力する事にします……もちろん、手は出しませんよ」","korean":"약속대로 시에 아가씨께 협조할게요…… 물론 손대지는 않아요.","recordingScript":"","memo":"음성 141","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":141,"id":"stage_r06h.mes#38387","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「ほ、本当ですか？」","korean":"저, 정말인가요?","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":142,"id":"stage_r06h.mes#38495","kind":"text","speaker":"토모키","english":"","japanese":"大樹「ええ……でも、最初に言った通り……俺が満足するまで茉莉子さんの身体で楽しんでから……ですが」","korean":"네…… 다만 처음 말한 대로…… 제가 만족할 때까지 마리코 씨의 몸으로 즐기고 나서요.","recordingScript":"","memo":"음성 143","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":143,"id":"stage_r06h.mes#38793","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「わ、わかり……ました……」","korean":"아, 알겠……어요……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":144,"id":"stage_r06h.mes#38909","kind":"text","speaker":"토모키","english":"","japanese":"大樹「それと、この事は俺は誰にも話しません……茉莉子さんだってそのほうがいいでしょ？」","korean":"그리고 이 일은 아무한테도 말 안 할게요…… 마리코 씨도 그게 좋죠?","recordingScript":"","memo":"음성 145","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":145,"id":"stage_r06h.mes#39195","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「そ、そうですけど……それの何処に貴方のメリットが？」","korean":"그, 그렇긴 한데…… 그래 봐야 하시즈메 씨한테 무슨 득이 있죠?","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":146,"id":"stage_r06h.mes#39337","kind":"text","speaker":"나레이션","english":"","japanese":"茉莉子にメリットはと問われ、俺はニヤリと顔をいやらしく歪ませた。","korean":"마리코가 무슨 이득이 있느냐고 묻자, 나는 입꼬리를 야릇하게 올렸다.","recordingScript":"","memo":"음성 147","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":147,"id":"stage_r06h.mes#39483","kind":"text","speaker":"토모키","english":"","japanese":"大樹「……その方が面白いじゃないですか」","korean":"……그편이 재밌잖아요.","recordingScript":"","memo":"음성 148","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":148,"id":"stage_r06h.mes#39723","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「お……おも……しろい？」","korean":"재…… 재미……있다고요?","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":149,"id":"stage_r06h.mes#39837","kind":"text","speaker":"토모키","english":"","japanese":"大樹「これから茉莉子さんは、事もあろうにアナルファックで紫衣お嬢様とするより強い快感を感じ、ハッスルしてしまうわけです」","korean":"이제 마리코 씨는 하필 이쪽으로, 시에 아가씨랑 할 때보다 훨씬 강한 쾌감을 느끼고 흥분할 거예요.","recordingScript":"","memo":"음성 150","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":150,"id":"stage_r06h.mes#40157","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「そ、そんな事……あ、ありえません……お尻を汚されて……紫衣お嬢様とするより、いいだなんて」","korean":"그, 그런 일은…… 이, 있을 리 없어요…… 엉덩이를 더럽혀지고서…… 시에 아가씨랑 할 때보다 좋을 리……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":151,"id":"stage_r06h.mes#40337","kind":"text","speaker":"토모키","english":"","japanese":"大樹「そして、今まで感じた事の無かった絶頂を全身で覚えた茉莉子さんは、何食わぬ顔で恋人と話し……何も知らぬお嬢様は身体を求めてくるでしょう……」","korean":"여태 몰랐던 절정을 온몸으로 기억한 마리코 씨가 아무 일 없던 얼굴로 연인과 얘기하겠죠…… 아무것도 모르는 아가씨는 마리코 씨 몸을 바라실 테고요……","recordingScript":"","memo":"음성 152","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":152,"id":"stage_r06h.mes#40681","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「う……うぐ……」","korean":"으…… 윽……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":153,"id":"stage_r06h.mes#40787","kind":"text","speaker":"토모키","english":"","japanese":"大樹「恋人の温もりを肌で感じているのに、茉莉子さんは俺のおちんちんの事で頭が一杯……愛撫されても大して感じていないのに喘ぐ演技をしちゃうわけです……」","korean":"연인의 온기를 느끼면서도 마리코 씨 머릿속에는 제 자지밖에 없을 거예요…… 애무를 받아도 별로 느껴지지 않으니 신음하는 척하겠죠……","recordingScript":"","memo":"음성 154","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":154,"id":"stage_r06h.mes#41019","kind":"text","speaker":"토모키","english":"","japanese":"大樹「考えるだけで、ワクワクしてきませんか？」","korean":"생각만 해도 기대되지 않아요?","recordingScript":"","memo":"음성 155","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":155,"id":"stage_r06h.mes#41265","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「……こ、この……外道……」","korean":"……이, 이…… 악질……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":156,"id":"stage_r06h.mes#41381","kind":"text","speaker":"토모키","english":"","japanese":"大樹「そうならないように、精々頑張って快感を耐えてください……紫衣お嬢様を裏切りたくないなら……」","korean":"그런 일이 없도록 쾌감에 죽어라 버텨 봐요…… 시에 아가씨를 배신하고 싶지 않으면요……","recordingScript":"","memo":"음성 157","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":157,"id":"stage_r06h.mes#41561","kind":"text","speaker":"나레이션","english":"","japanese":"腰をがっしりと掴むと、進入を拒む括約筋の力に負けじと肉棒を力強く奥へとめり込ませていく。","korean":"허리를 꽉 움켜쥐고, 들어오지 못하게 조이는 괄약근에 맞서 육봉을 깊숙이 밀어 넣었다.","recordingScript":"","memo":"음성 158","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":158,"id":"stage_r06h.mes#41849","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あぐ、い、嫌っ、嫌ぁ！　あ、あぁん！　や、止めて、あ、あぐっ、んあ、あ、ああっ、んんっ、んあぁぁん！」","korean":"아윽, 시, 싫어요, 싫다고요! 아, 아앙! 그, 그만해요, 아, 아윽, 아, 아, 아앗, 으응, 아아앙!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":159,"id":"stage_r06h.mes#42353","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んぐぅ、んひぃいいいいいい！　……んはぁ、んんっ、んぐっ……あ、あぐうぅ……んはぁ、んはぁ……」","korean":"으윽, 꺄아악! ……하아, 으응, 윽…… 아, 아으윽…… 하아, 하아……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":160,"id":"stage_r06h.mes#42539","kind":"text","speaker":"나레이션","english":"","japanese":"尻穴から広がる刺激に悶える茉莉子に呼吸を整える暇を与えず、俺は肉棒で彼女のアナルを蹂躙し始めた。","korean":"항문에서 퍼지는 자극에 몸을 뒤트는 마리코에게 숨 돌릴 틈도 주지 않고, 육봉으로 거칠게 범하기 시작했다.","recordingScript":"","memo":"음성 161","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":161,"id":"stage_r06h.mes#43059","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んおぉ！　あ、あぐぅ、んんっ、んひぃ、あ、あぐっ、んぐっ、んはぁ、ああっ……ああぁ……」","korean":"오옷! 아, 아으윽, 으응, 꺅, 아, 아윽, 윽, 하아, 아앗…… 아아……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":162,"id":"stage_r06h.mes#43355","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んああ、ああぁん……あくっ、んんっ、んあ、あ、ああっ、あぐっ、あ、ああぁ、ああぁん……んあぁぁ」","korean":"아아, 아아앙…… 으윽, 으응, 아, 아, 아앗, 아윽, 아, 아아, 아아앙…… 아아아.","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":163,"id":"stage_r06h.mes#43541","kind":"text","speaker":"토모키","english":"","japanese":"大樹「ほらほら……もうエッチな声色に……頑張って耐えないと、紫衣お嬢様じゃイケなくなってしまいますよ？」","korean":"봐요, 벌써 야한 소리가 나는데요…… 잘 참지 않으면 시에 아가씨와 할 때는 절정에 못 이를걸요?","recordingScript":"","memo":"음성 164","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":164,"id":"stage_r06h.mes#43985","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んぎっ、んんっ、んぐぅ……か、感じない……あ、あぐぅ、んんっ、んはぁ！　こんなの……んんっ、こんなの感じないぃ……んはぁ、あぐっ、んあっ、んはぁあ！」","korean":"으악, 으응, 으윽…… 아, 아무 느낌도…… 아, 아으윽, 으응, 하아! 이딴 건…… 으응, 이딴 건 안 느껴요…… 하아, 아윽, 아, 하아아!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":165,"id":"stage_r06h.mes#44225","kind":"text","speaker":"나레이션","english":"","japanese":"茉莉子の快感に抵抗する気持ちが乗り移ったかのように、菊門がギュウッと締まり肉棒の動きを阻害していく。","korean":"쾌감을 거부하는 마리코의 마음이 옮겨가기라도 한 듯 항문이 꽉 조이면서 육봉을 움직이기 힘들어졌다.","recordingScript":"","memo":"음성 166","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":166,"id":"stage_r06h.mes#44407","kind":"text","speaker":"나레이션","english":"","japanese":"それに負けじと腰に力を入れ、肉竿にへばりつく肛門の皮が捲れて伸びるほど長い大きなストロークで、彼女に強い刺激を与え続けた。","korean":"지지 않으려고 허리에 힘을 줬다. 육봉에 달라붙은 살이 딸려 나올 정도로 크게 움직이며 강한 자극을 이어 갔다.","recordingScript":"","memo":"음성 167","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":167,"id":"stage_r06h.mes#44869","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あぐぅ！　あ、あっ、ああっ！　あひぃ！　あぐぅ、いぃ、いやぁああ！　あ、ああっ、あふぅ、あ、あひぃ！」","korean":"아으윽! 아, 앗, 아앗! 꺅! 아으윽, 시, 싫어요! 아, 아앗, 하으, 아, 꺅!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":168,"id":"stage_r06h.mes#45179","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あぐ、あぁん！　駄目ぇ……んんっ、んぐぅ、入ってくるぅ、お尻の穴……締めても、締めてもおちんちん入ってくるぅ……あ、あぐぅ……お、お嬢様……お嬢様ぁああ！」","korean":"아윽, 아앙! 안 돼요…… 으응, 으윽, 들어와요, 엉덩이에…… 아무리 조여도 자지가 들어온다고요…… 아, 아으윽…… 아, 아가씨…… 아가씨!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":169,"id":"stage_r06h.mes#45425","kind":"text","speaker":"토모키","english":"","japanese":"大樹「くぅ……締まる……いいですよ、茉莉子さん……茉莉子さんも気持ちいいですか？」","korean":"으윽…… 조인다…… 좋아요, 마리코 씨…… 마리코 씨도 기분 좋아요?","recordingScript":"","memo":"음성 170","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":170,"id":"stage_r06h.mes#45707","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「はぁう、んんっ、んあっ！　あ、あぐっ、い、嫌ぁ……あ、ああっ、あぐぅ……いっ、いい……んぐぅ、んはぁ、いい、いい、いいっ、んはぁ！　い、いいっ！」","korean":"하으, 으응, 아! 아, 아윽, 시, 싫어요…… 아, 아앗, 아으윽…… 조, 좋아…… 으윽, 하아, 좋아, 좋아, 좋아, 하아! 조, 좋아요!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":171,"id":"stage_r06h.mes#46201","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「はぁん、お、お嬢様、お嬢様ぁ……あ、あく、あ、ああぁん、い、いくぅ、いくぅう、いくっ、いくぅ、い、いぐぅうううう！」","korean":"하앙, 아, 아가씨, 아가씨…… 아, 으윽, 아, 아아앙, 가, 가요, 가요, 가요, 가요, 가, 가아아아!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":172,"id":"stage_r06h.mes#46525","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あはぁ、ああっ、あぁん！　い、いっ、いくぅううううぅぅぅううううう！！！」","korean":"아하아, 아앗, 아앙! 가, 가, 가아아아아!!!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":173,"id":"stage_r06h.mes#46689","kind":"text","speaker":"나레이션","english":"","japanese":"絶頂の叫びと共にギュウギュウと収縮を繰り返す菊門に刺激を受け膨張を増したペニスで、穴を拡張するように力強く抽送を繰り返していく。","korean":"절정의 비명과 함께 항문이 거듭 꽉 수축했다. 그 자극에 더 부푼 페니스로 안을 넓히듯 반복해서 힘껏 밀어 넣었다.","recordingScript":"","memo":"음성 174","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":174,"id":"stage_r06h.mes#47017","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んおぉおぉ……おふぅ、んおぉおお！　つ、強いぃ！　緩めてぇ！　んおぉ、んおぉぉ！」","korean":"오오…… 오흐, 오오오! 너, 너무 세요! 살살 해 줘요! 오오, 오오오!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":175,"id":"stage_r06h.mes#47189","kind":"text","speaker":"토모키","english":"","japanese":"大樹「んはぁ、はぁ、んぐっ……も、もうすぐ……精液を、ケツ穴に流し込んであげますね……」","korean":"하아, 하아, 윽…… 고, 곧…… 엉덩이 안에 정액을 쏟아 줄게요……","recordingScript":"","memo":"음성 176","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":176,"id":"stage_r06h.mes#47477","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あぐ、はぁ、んはぁ！　あ、あぐぅ、んぉおお……きちゃう……あ、あぐぅ、くる、くるぅ！」","korean":"아윽, 하아, 하아! 아, 아으윽, 오오오…… 오고 있어요…… 아, 아으윽, 온다, 온다고요!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":177,"id":"stage_r06h.mes#47653","kind":"text","speaker":"나레이션","english":"","japanese":"何度も直腸をズリズリと擦っていたペニスの先端に硬いものが当たり、俺はその感触へ狙いを定め腰を振りたてる。","korean":"직장 안쪽을 몇 번이고 문지르던 페니스 끝에 단단한 게 닿았다. 그 감촉을 겨냥해 허리를 흔들었다.","recordingScript":"","memo":"음성 178","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":178,"id":"stage_r06h.mes#48097","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んほぉおお！　し、子宮ぅ！　んはぁ、あぐぅ！　お、おちんちんが子宮に、子宮に当たって……んはぁ、んおぉ、こ、腰がジンジンするぅ！　あ、あぐぅ、んあぁ！」","korean":"오오오! 자, 자궁이! 하아, 아으윽! 자, 자지가 자궁에, 자궁에 닿아서…… 하아, 오오, 허, 허리가 찌릿해요! 아, 아으윽, 아아!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":179,"id":"stage_r06h.mes#48339","kind":"text","speaker":"토모키","english":"","japanese":"大樹「んくっ……あくぅ！　んんっ、茉莉子さん、出ますよ……このまま、んぐっ……はぁ、はぁ！」","korean":"윽…… 으윽! 으응, 마리코 씨, 나와요…… 이대로, 윽…… 하아, 하아!","recordingScript":"","memo":"음성 180","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":180,"id":"stage_r06h.mes#48631","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あぐぅん！　い、痛いぃ！　あ、あくぅ……い、痛いのにぃ……い、いくぅ！　あぐぅ、あ、あはぁ……いい……痛い……いいっ……ああ、いやぁ、こんなの嫌ぁ……」","korean":"아으윽! 아, 아파요! 아, 으윽…… 아, 아픈데…… 가, 가요! 아으윽, 아, 아하아…… 좋아…… 아파…… 좋아요…… 아아, 싫어, 이런 건 싫어요……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":181,"id":"stage_r06h.mes#48991","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「ああぁ……い、いぐぅ……お嬢様、お嬢様ぁ……も、もう駄目……気持ち……気持ちよすぎて……こ、こわ……れるぅうううう」","korean":"아아…… 가, 가요…… 아가씨, 아가씨…… 이, 이제 안 돼요…… 기분이…… 너무 좋아서…… 마, 망가……져요……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":182,"id":"stage_r06h.mes#49315","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「いぐぅ、いぐぅううう！」","korean":"가요, 가아아아!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":183,"id":"stage_r06h.mes#49429","kind":"text","speaker":"토모키","english":"","japanese":"大樹「ま、茉莉子！　でっ、出るぅ！」","korean":"마, 마리코! 나, 나온다!","recordingScript":"","memo":"음성 184","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":184,"id":"stage_r06h.mes#49547","kind":"text","speaker":"나레이션","english":"","japanese":"突き入れた肉棒の先で壁越しに子宮へ強く押し付け、俺は込み上げた欲望を吐き出させた。","korean":"깊숙이 넣은 육봉 끝으로 벽 너머 자궁을 힘껏 누른 채, 차오른 욕망을 쏟아 냈다.","recordingScript":"","memo":"음성 185","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":185,"id":"stage_r06h.mes#50102","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んぉおおお！　あ、あぐぅ、熱い、熱いのが弾けて、あ、ああっ、んあぁっ！　く、くるっ、きたぁ！」","korean":"오오오! 아, 아으윽, 뜨거워, 뜨거운 게 터져서, 아, 아앗, 아아! 오, 온다, 왔어요!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":186,"id":"stage_r06h.mes#50404","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あひぃ、あぐぅ！　い、いくぅ！　いくぅうう、いっ、いいっ、いくぅうううぅぅぅううう！！！」","korean":"꺅, 아으윽! 가, 가요! 가요, 가, 가, 가아아아아!!!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":187,"id":"stage_r06h.mes#50584","kind":"text","speaker":"나레이션","english":"","japanese":"自らより子宮口に亀頭を押し付けるように、茉莉子は尻を振りたてていく。","korean":"마리코는 귀두가 자궁 입구 쪽을 더 누르도록 제 쪽에서 엉덩이를 흔들었다.","recordingScript":"","memo":"음성 188","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":188,"id":"stage_r06h.mes#50734","kind":"text","speaker":"나레이션","english":"","japanese":"俺はそんな茉莉子の腰をガッチリと引き寄せ、込み上げる熱い白濁を次々と直腸へと注ぎ込む。","korean":"그 허리를 단단히 끌어당겨, 뜨겁게 차오르는 흰 정액을 직장에 잇따라 쏟았다.","recordingScript":"","memo":"음성 189","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":189,"id":"stage_r06h.mes#51020","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「おおぅ……んおぉおお……熱いぃ……おちんぽから、熱い精液がどんどん入ってくるぅ……」","korean":"오오…… 오오오…… 뜨거워요…… 자지에서 뜨거운 정액이 자꾸 들어와요……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":190,"id":"stage_r06h.mes#51312","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んああぁ……お嬢様ぁ……お嬢様ぁあぁ……おちんぽいいですぅ……んはぁ、はあぁ……んおぉ……気持ち……いいぃ……」","korean":"아아아…… 아가씨…… 아가씨…… 자지 좋아요…… 하아, 하아…… 오오…… 기분…… 좋아요……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":191,"id":"stage_r06h.mes#51681","kind":"text","speaker":"나레이션","english":"","japanese":"うわ言のように言葉を漏らす茉莉子のアヌスから、固さを失わぬ肉棒をズルリと引き抜いていく。","korean":"헛소리처럼 말을 흘리는 마리코의 항문에서, 아직 단단한 육봉을 길게 빼냈다.","recordingScript":"","memo":"음성 192","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":192,"id":"stage_r06h.mes#51851","kind":"text","speaker":"나레이션","english":"","japanese":"すると開いたままの穴の奥から精液とお酒がコポコポと零れ出してきた。","korean":"벌어진 구멍 깊은 곳에서 정액과 술이 보글보글 흘러나왔다.","recordingScript":"","memo":"음성 193","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":193,"id":"stage_r06h.mes#52117","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あはぁ、あぐぅう……んあぁ……んはぁ……」","korean":"아하아, 아으윽…… 아아…… 하아……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":194,"id":"stage_r06h.mes#52249","kind":"text","speaker":"토모키","english":"","japanese":"大樹「まだ終わりじゃないですからね……今度は、おまんこで気持ちよくさせてあげますよ」","korean":"아직 안 끝났어요…… 이번엔 보지로 기분 좋게 해 줄게요.","recordingScript":"","memo":"음성 195","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":195,"id":"stage_r06h.mes#52673","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あはぁあん……あ、あふぅう……んほぉ……おちんぽがおまんこに入って、入ってきたぁ……ああ……んあぁぁ……」","korean":"아하앙…… 아, 하으…… 오오…… 자지가 보지에 들어와, 들어와요…… 아아…… 아아아……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":196,"id":"stage_r06h.mes#52869","kind":"text","speaker":"나레이션","english":"","japanese":"蜜壷に入れなおすと、ユルユルだった先ほどとはうって変わり、貪欲に肉棒を欲しヒダが忙しなく肉棒に絡みついてきた。","korean":"질에 다시 넣자, 아까처럼 헐겁기는커녕 육봉이 아쉬웠다는 듯 질벽의 주름이 바쁘게 감겨 들었다.","recordingScript":"","memo":"음성 197","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":197,"id":"stage_r06h.mes#53061","kind":"text","speaker":"토모키","english":"","japanese":"大樹「ふふ……チンポは気に入りましたか？」","korean":"후후…… 자지가 마음에 들었어요?","recordingScript":"","memo":"음성 198","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":198,"id":"stage_r06h.mes#53303","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「は、はいぃ……いいですぅ……紫衣お嬢様……このおちんぽ最高です……」","korean":"네, 네에…… 좋아요…… 시에 아가씨…… 이 자지, 최고예요……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":199,"id":"stage_r06h.mes#53461","kind":"text","speaker":"토모키","english":"","japanese":"大樹「気に入ってもらえてよかった……折角ですし、もう一度中に出して男に縁のなさそうな茉莉子さんに種付けしてあげましょう」","korean":"마음에 들어서 다행이네요…… 이왕이면 한 번 더 안에 싸서, 남자하고는 인연이 없어 보이는 마리코 씨를 임신시켜 줄게요.","recordingScript":"","memo":"음성 200","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":200,"id":"stage_r06h.mes#53750","kind":"text","speaker":"나레이션","english":"","japanese":"たっぷりと発情し種付けを望み降りてきた子宮を、固く怒張した亀頭でズンズンと突きまくる。","korean":"한껏 달아오른 몸에서 씨를 바라듯 내려온 자궁을, 불끈 선 귀두로 몇 번이고 세게 밀어붙였다.","recordingScript":"","memo":"음성 201","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":201,"id":"stage_r06h.mes#54036","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んおぉお！　あふぅ、ひぃ……子宮ぅ……んおおぉ、んはぁ、ああっ！　し、子宮に響くぅうう……」","korean":"오오! 하으, 꺅…… 자궁…… 오오, 하아, 아앗! 자, 자궁까지 울려요……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":202,"id":"stage_r06h.mes#54336","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あふぅ、ああっ、あひぃ！　ああっ、あふぅう！　くる、ああっ、いくぅ、もういくぅ！　あ、あぐぅ、ああっ、ああぁん！」","korean":"하으, 아앗, 꺅! 아앗, 하으! 온다, 아앗, 가요, 이제 가요! 아, 아으윽, 아앗, 아아앙!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":203,"id":"stage_r06h.mes#54658","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「あっ、ああっ、あぐぅ！　ああっ、あああっ、あああぁああああああ！！！」","korean":"앗, 아앗, 아으윽! 아앗, 아아앗, 아아아아아!!!","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":204,"id":"stage_r06h.mes#54933","kind":"text","speaker":"토모키","english":"","japanese":"大樹「っ！？　んぐぉ……」","korean":"……?! 으윽……","recordingScript":"","memo":"음성 205","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":205,"id":"stage_r06h.mes#55041","kind":"text","speaker":"나레이션","english":"","japanese":"突然湧き上がった頭痛を堪えようと、俺はぐっと歯を食いしばる。","korean":"갑자기 치밀어 오른 두통을 참으려고 이를 악물었다.","recordingScript":"","memo":"음성 206","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":206,"id":"stage_r06h.mes#55183","kind":"text","speaker":"토모키","english":"","japanese":"大樹（……く、くそ……これからって時に……）","korean":"……제, 젠장…… 이제부터인데……","recordingScript":"","memo":"음성 207","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":207,"id":"stage_r06h.mes#55427","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んあぁ……もっとぉ……もっとおちんぽ、感じさせてくださいぃ……」","korean":"아아…… 더…… 자지로 더 느끼게 해 줘요……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":208,"id":"stage_r06h.mes#55581","kind":"text","speaker":"토모키","english":"","japanese":"大樹「んぐぅ……ま、まかせてください……たっぷりと感じさせてあげますよ……」","korean":"으윽…… 마, 맡겨 주세요…… 실컷 느끼게 해 줄게요……","recordingScript":"","memo":"음성 209","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":209,"id":"stage_r06h.mes#56223","kind":"text","speaker":"나레이션","english":"","japanese":"そう言ったものの、頭痛だけでなく視界もグラつきだし、このままの姿勢で続けるのは困難……","korean":"그렇게 말은 했지만 머리만 아픈 게 아니라 시야까지 흔들렸다. 이 자세로 계속하기는 힘들었다……","recordingScript":"","memo":"음성 210","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":210,"id":"stage_r06h.mes#56391","kind":"text","speaker":"나레이션","english":"","japanese":"部屋は暗く、ズボンを探すには部屋の明かりをつけなければならない。","korean":"방이 어두웠다. 바지를 찾으려면 불부터 켜야 했다.","recordingScript":"","memo":"음성 211","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":211,"id":"stage_r06h.mes#56537","kind":"text","speaker":"나레이션","english":"","japanese":"……俺は束縛を解いた茉莉子を仰向けにすると、眩暈から逃れるようにしがみ付く。","korean":"……마리코를 풀어 주고 반듯이 눕힌 뒤, 현기증을 떨치려는 듯 마리코에게 매달렸다.","recordingScript":"","memo":"음성 212","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":212,"id":"stage_r06h.mes#56695","kind":"text","speaker":"토모키","english":"","japanese":"大樹「い、いきます……茉莉子さんも動いてください……」","korean":"가, 갑니다…… 마리코 씨도 움직여 주세요……","recordingScript":"","memo":"음성 213","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":213,"id":"stage_r06h.mes#56949","kind":"text","speaker":"마리코","english":"","japanese":"茉莉子「んあぁ……おちんちん……きてぇ……」","korean":"아아…… 자지…… 들어와요……","recordingScript":"","memo":"","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":214,"id":"stage_r06h.mes#57075","kind":"text","speaker":"나레이션","english":"","japanese":"グルグルと回る不快な感覚の中……","korean":"빙글빙글 도는 불쾌한 감각 속에서……","recordingScript":"","memo":"음성 215","voice":"","phaseId":"stage_r06h-P1"},
{"rowNumber":215,"id":"stage_r06h.mes#57243","kind":"text","speaker":"나레이션","english":"","japanese":"背中へ手足を巻きつけてきた茉莉子の子宮に子種を流し込む為……俺はゆるゆると腰を振り始めた……","korean":"내 등에 팔다리를 감은 마리코의 자궁에 씨를 뿌리려고…… 느릿하게 허리를 흔들기 시작했다……","recordingScript":"","memo":"음성 216","voice":"","phaseId":"stage_r06h-P1"}
];
